116	public class Application {
117	    private static final Logger logger = LoggerFactory.getLogger(Application.class);
118	
119	    public static void main(String[] args) {
120	        String dbUrl = System.getenv("DB_URL");
121	        String dbUser = System.getenv("DB_USER");
122	        String dbPassword = System.getenv("DB_PASSWORD");
123	        String portStr = System.getenv("PORT");
124	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
125	
126	        if (dbUrl == null || dbUser == null || dbPassword == null) {
127	            logger.error("Missing required environment variables: DB_URL, DB_USER, DB_PASSWORD");
128	            System.exit(1);
129	        }
130	
131	        Database.initialize(dbUrl, dbUser, dbPassword);
132	
133	        Gson gson = new GsonBuilder()
134	            .setPrettyPrinting()
135	            .create();
136	
137	        RoomRepository roomRepository = new RoomRepository();
138	        ReservationRepository reservationRepository = new ReservationRepository();
139	        MessageRepository messageRepository = new MessageRepository();
140	
141	        ReservationService reservationService = new ReservationService(reservationRepository, roomRepository);
142	        ReceiptService receiptService = new ReceiptService(roomRepository);
143	        EmailService emailService = new EmailService(messageRepository, receiptService);
144	
145	        ReportRegistry reportRegistry = new ReportRegistry();
146	        reportRegistry.register("occupancy", new OccupancyReport(roomRepository, reservationRepository));
147	        reportRegistry.register("revenue", new RevenueReport(reservationRepository));
148	        reportRegistry.register("tourism-tax", new TourismTaxReport(reservationRepository));
149	        reportRegistry.register("rate-plans", new RatePlansReport(reservationRepository));
150	
151	        RoomsHandler roomsHandler = new RoomsHandler(roomRepository, gson);
152	        ReservationsHandler reservationsHandler = new ReservationsHandler(reservationService, emailService, receiptService, roomRepository, gson);
153	        MessagesHandler messagesHandler = new MessagesHandler(messageRepository, gson);
154	        ReportsHandler reportsHandler = new ReportsHandler(reportRegistry);
155	
156	        Javalin app = Javalin.create()
157	            .get("/rooms", roomsHandler::listRooms)
158	            .post("/reservations", reservationsHandler::createReservation)
159	            .get("/reservations/{id}", reservationsHandler::getReservation)
160	            .post("/reservations/{id}/confirmation", reservationsHandler::confirmReservation)
161	            .post("/reservations/{id}/cancellation", reservationsHandler::cancelReservation)
162	            .post("/reservations/{id}/check-in", reservationsHandler::checkInReservation)
163	            .post("/reservations/{id}/check-out", reservationsHandler::checkOutReservation)
164	            .get("/reservations/{id}/document", reservationsHandler::getDocument)
165	            .get("/messages", messagesHandler::listMessages)
166	            .get("/reports/occupancy", reportsHandler::getOccupancyReport)
167	            .get("/reports/revenue", reportsHandler::getRevenueReport)
168	            .get("/reports/tourism-tax", reportsHandler::getTourismTaxReport)
169	            .get("/reports/rate-plans", reportsHandler::getRatePlansReport);
170	
171	        app.start(port);
172	        logger.info("Application started on port {}", port);
173	    }
174	}
