186	public class MessagesHandler {
187	    private final MessageRepository messageRepository;
188	    private final Gson gson;
189	
190	    public MessagesHandler(MessageRepository messageRepository, Gson gson) {
191	        this.messageRepository = messageRepository;
192	        this.gson = gson;
193	    }
194	
195	    public void listMessages(Context ctx) {
196	        List<Message> messages = messageRepository.findAll();
197	        JsonArray jsonArray = new JsonArray();
198	
199	        for (Message msg : messages) {
200	            JsonObject json = new JsonObject();
201	            json.addProperty("id", msg.getId());
202	            json.addProperty("channel", msg.getChannel());
203	            json.addProperty("to", msg.getTo());
204	            json.addProperty("subject", msg.getSubject());
205	            json.addProperty("body", msg.getBody());
206	            jsonArray.add(json);
207	        }
208	
209	        ctx.json(jsonArray);
210	    }
211	}
