225	public class ReportsHandler {
226	    private static final Logger logger = LoggerFactory.getLogger(ReportsHandler.class);
227	    private final ReportRegistry reportRegistry;
228	
229	    public ReportsHandler(ReportRegistry reportRegistry) {
230	        this.reportRegistry = reportRegistry;
231	    }
232	
233	    public void getOccupancyReport(Context ctx) {
234	        try {
235	            String dateStr = ctx.queryParam("date");
236	            if (dateStr == null) {
237	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
238	                return;
239	            }
240	
241	            LocalDate date = LocalDate.parse(dateStr, DateTimeFormatter.ofPattern("yyyy-MM-dd"));
242	            Report report = reportRegistry.get("occupancy");
243	            String csv = report.generate(date);
244	            ctx.contentType("text/csv;charset=utf-8").result(csv);
245	        } catch (DateTimeParseException e) {
246	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
247	        } catch (Exception e) {
248	            logger.error("Error generating occupancy report", e);
249	            ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "Error generating report"));
250	        }
251	    }
