343	public class ReservationsHandler {
344	    private static final Logger logger = LoggerFactory.getLogger(ReservationsHandler.class);
345	    private final ReservationService reservationService;
346	    private final EmailService emailService;
347	    private final ReceiptService receiptService;
348	    private final RoomRepository roomRepository;
349	    private final Gson gson;
350	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
351	
352	    public ReservationsHandler(ReservationService reservationService, EmailService emailService,
353	                              ReceiptService receiptService, RoomRepository roomRepository, Gson gson) {
354	        this.reservationService = reservationService;
355	        this.emailService = emailService;
356	        this.receiptService = receiptService;
357	        this.roomRepository = roomRepository;
358	        this.gson = gson;
359	    }
360	
361	    public void createReservation(Context ctx) {
362	        try {
363	            JsonObject body = ctx.bodyAsClass(JsonObject.class);
364	
365	            if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
366	                !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
367	                !body.has("guests") || !body.has("ratePlan")) {
368	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
369	                return;
370	            }
371	
372	            int roomNumber = body.get("roomNumber").getAsInt();
373	            String guestName = body.get("guestName").getAsString();
374	            String guestEmail = body.get("guestEmail").getAsString();
375	            String guestCpf = body.get("guestCpf").getAsString();
376	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").getAsString(), DATE_FORMAT);
377	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString(), DATE_FORMAT);
378	            int guests = body.get("guests").getAsInt();
379	            Reservation.RatePlan ratePlan = Reservation.RatePlan.valueOf(body.get("ratePlan").getAsString());
380	
381	            Reservation reservation = reservationService.createReservation(roomNumber, guestName, guestEmail, guestCpf,
382	                checkIn, checkOut, guests, ratePlan);
383	
384	            ctx.status(201).json(toResponseDto(reservation));
385	        } catch (IllegalArgumentException e) {
386	            handleError(ctx, e.getMessage());
387	        } catch (Exception e) {
388	            logger.error("Error creating reservation", e);
389	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request format"));
390	        }
391	    }
392	
393	    public void getReservation(Context ctx) {
394	        try {
395	            long id = ctx.pathParamAsClass("id", Long.class).get();
396	            Reservation reservation = reservationService.getReservation(id);
397	            ctx.json(toResponseDto(reservation));
398	        } catch (IllegalArgumentException e) {
399	            handleError(ctx, e.getMessage());
400	        } catch (Exception e) {
401	            logger.error("Error getting reservation", e);
402	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
403	        }
404	    }
405	
406	    public void confirmReservation(Context ctx) {
407	        try {
408	            long id = ctx.pathParamAsClass("id", Long.class).get();
409	            JsonObject body = ctx.bodyAsClass(JsonObject.class);
410	
411	            if (!body.has("amountPaid")) {
412	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing amountPaid"));
413	                return;
414	            }
415	
416	            BigDecimal amountPaid = body.get("amountPaid").getAsBigDecimal();
417	            Reservation reservation = reservationService.confirm(id, amountPaid);
418	
419	            emailService.sendConfirmationEmail(reservation);
420	
421	            ctx.json(toResponseDto(reservation));
422	        } catch (IllegalArgumentException e) {
423	            handleError(ctx, e.getMessage());
424	        } catch (Exception e) {
425	            logger.error("Error confirming reservation", e);
426	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
427	        }
428	    }
