442	
443	    public void checkOutReservation(Context ctx) {
444	        try {
445	            long id = ctx.pathParamAsClass("id", Long.class).get();
446	            Reservation reservation = reservationService.checkOut(id);
447	
448	            String receipt = receiptService.generateReceipt(reservation);
449	            JsonObject response = new JsonObject();
450	            response.addProperty("title", "Comprovante de reserva");
451	            response.addProperty("reservationId", reservation.getId());
452	            response.addProperty("guestName", reservation.getGuestName());
453	            response.addProperty("guestCpf", reservation.getGuestCpf());
454	            response.addProperty("roomNumber", reservation.getRoomNumber());
455	            response.addProperty("roomType", getRoomType(reservation.getRoomNumber()));
456	            response.addProperty("checkIn", reservation.getCheckIn().format(DATE_FORMAT));
457	            response.addProperty("checkOut", reservation.getCheckOut().format(DATE_FORMAT));
458	            response.addProperty("nights", reservation.getNights());
459	            response.addProperty("subtotal", reservation.getSubtotal());
460	            response.addProperty("discount", reservation.getDiscount());
461	            response.addProperty("total", reservation.getTotal());
462	
463	            ctx.json(response);
464	        } catch (IllegalArgumentException e) {
465	            handleError(ctx, e.getMessage());
466	        } catch (Exception e) {
467	            logger.error("Error checking out reservation", e);
468	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
469	        }
470	    }
