485	    public void getDocument(Context ctx) {
486	        try {
487	            long id = ctx.pathParamAsClass("id", Long.class).get();
488	            Reservation reservation = reservationService.getReservation(id);
489	
490	            if (reservation.getStatus() != Reservation.Status.CONFIRMED &&
491	                reservation.getStatus() != Reservation.Status.CHECKED_IN &&
492	                reservation.getStatus() != Reservation.Status.CHECKED_OUT) {
493	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document not available"));
494	                return;
495	            }
496	
497	            String receipt = receiptService.generateReceipt(reservation);
498	            JsonObject response = new JsonObject();
499	            response.addProperty("title", "Comprovante de reserva");
500	            response.addProperty("reservationId", reservation.getId());
501	            response.addProperty("guestName", reservation.getGuestName());
502	            response.addProperty("guestCpf", reservation.getGuestCpf());
503	            response.addProperty("roomNumber", reservation.getRoomNumber());
504	            response.addProperty("roomType", getRoomType(reservation.getRoomNumber()));
505	            response.addProperty("checkIn", reservation.getCheckIn().format(DATE_FORMAT));
506	            response.addProperty("checkOut", reservation.getCheckOut().format(DATE_FORMAT));
507	            response.addProperty("nights", reservation.getNights());
508	            response.addProperty("subtotal", reservation.getSubtotal());
509	            response.addProperty("discount", reservation.getDiscount());
510	            response.addProperty("total", reservation.getTotal());
511	
512	            ctx.json(response);
513	        } catch (IllegalArgumentException e) {
514	            handleError(ctx, e.getMessage());
515	        } catch (Exception e) {
516	            logger.error("Error getting document", e);
517	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
518	        }
519	    }
520	
521	    private Object toResponseDto(Reservation reservation) {
522	        JsonObject response = new JsonObject();
523	        response.addProperty("id", reservation.getId());
524	        response.addProperty("roomNumber", reservation.getRoomNumber());
525	        response.addProperty("guestName", reservation.getGuestName());
526	        response.addProperty("guestEmail", reservation.getGuestEmail());
527	        response.addProperty("guestCpf", reservation.getGuestCpf());
528	        response.addProperty("checkIn", reservation.getCheckIn().format(DATE_FORMAT));
529	        response.addProperty("checkOut", reservation.getCheckOut().format(DATE_FORMAT));
530	        response.addProperty("guests", reservation.getGuests());
531	        response.addProperty("ratePlan", reservation.getRatePlan().toString());
532	        response.addProperty("nights", reservation.getNights());
533	        response.addProperty("subtotal", reservation.getSubtotal());
534	        response.addProperty("discount", reservation.getDiscount());
535	        response.addProperty("total", reservation.getTotal());
536	        response.addProperty("status", reservation.getStatus().toString());
537	        response.addProperty("amountPaid", reservation.getAmountPaid());
538	        response.addProperty("refund", reservation.getRefund());
539	        return response;
540	    }
541	
542	    private String getRoomType(int roomNumber) {
543	        Optional<Room> room = roomRepository.findByNumber(roomNumber);
544	        return room.map(r -> r.type().toString()).orElse("UNKNOWN");
545	    }
546	
547	    private void handleError(Context ctx, String errorCode) {
548	        switch (errorCode) {
549	            case "ROOM_NOT_FOUND":
550	                ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
551	                break;
552	            case "RESERVATION_NOT_FOUND":
553	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
554	                break;
555	            case "ROOM_UNAVAILABLE":
556	                ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room not available for those dates"));
557	                break;
558	            case "CAPACITY_EXCEEDED":
559	                ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Too many guests for this room"));
560	                break;
561	            case "OPERATION_NOT_ALLOWED":
562	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for this reservation status"));
563	                break;
564	            case "INVALID_REQUEST":
565	            default:
566	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
567	                break;
568	        }
569	    }
570	
571	    static class ErrorResponse {
572	        String error;
573	        String message;
574	
575	        ErrorResponse(String error, String message) {
576	            this.error = error;
577	            this.message = message;
578	        }
579	    }
580	}
