    17	public class ReservationService {
    18	    private static final Logger logger = LoggerFactory.getLogger(ReservationService.class);
    19	    private final ReservationRepository reservationRepository;
    20	    private final RoomRepository roomRepository;
    21	
    22	    public ReservationService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
    23	        this.reservationRepository = reservationRepository;
    24	        this.roomRepository = roomRepository;
