    26	
    27	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    28	                                       LocalDate checkIn, LocalDate checkOut, int guests, Reservation.RatePlan ratePlan) {
    29	        Optional<Room> room = roomRepository.findByNumber(roomNumber);
    30	        if (room.isEmpty()) {
    31	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    32	        }
    33	
    34	        if (guests < 1) {
    35	            throw new IllegalArgumentException("INVALID_REQUEST");
    36	        }
    37	
    38	        if (guests > room.get().capacity()) {
    39	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
    40	        }
    41	
    42	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    43	            throw new IllegalArgumentException("INVALID_REQUEST");
    44	        }
    45	
    46	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
    47	        if (!conflicts.isEmpty()) {
    48	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    49	        }
    50	
    51	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    52	        BigDecimal subtotal = calculateNightsCost(room.get(), checkIn, checkOut);
    53	        BigDecimal discount = calculateDiscount(subtotal, ratePlan);
    54	        BigDecimal total = Money.subtract(subtotal, discount);
    55	
    56	        Reservation reservation = new Reservation();
    57	        reservation.setRoomNumber(roomNumber);
    58	        reservation.setGuestName(guestName);
    59	        reservation.setGuestEmail(guestEmail);
    60	        reservation.setGuestCpf(guestCpf);
    61	        reservation.setCheckIn(checkIn);
    62	        reservation.setCheckOut(checkOut);
    63	        reservation.setGuests(guests);
    64	        reservation.setRatePlan(ratePlan);
    65	        reservation.setNights(nights);
    66	        reservation.setSubtotal(subtotal);
    67	        reservation.setDiscount(discount);
    68	        reservation.setTotal(total);
    69	        reservation.setStatus(Reservation.Status.PENDING);
    70	        reservation.setAmountPaid(BigDecimal.ZERO);
    71	        reservation.setRefund(null);
    72	
    73	        return reservationRepository.save(reservation);
    74	    }
    75	
    76	    public Reservation getReservation(long id) {
    77	        return reservationRepository.findById(id)
    78	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
    79	    }
    80	
    81	    public Reservation confirm(long id, BigDecimal amountPaid) {
    82	        Reservation reservation = getReservation(id);
    83	
    84	        if (reservation.getStatus() != Reservation.Status.PENDING) {
    85	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    86	        }
    87	
    88	        reservation.setStatus(Reservation.Status.CONFIRMED);
    89	        reservation.setAmountPaid(amountPaid);
    90	
    91	        reservationRepository.update(reservation);
    92	        return reservation;
    93	    }
    94	
    95	    public Reservation checkIn(long id) {
    96	        Reservation reservation = getReservation(id);
    97	
    98	        if (reservation.getStatus() != Reservation.Status.CONFIRMED) {
    99	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   100	        }
   101	
   102	        reservation.setStatus(Reservation.Status.CHECKED_IN);
   103	        reservationRepository.update(reservation);
   104	        return reservation;
   105	    }
   106	
   107	    public Reservation checkOut(long id) {
   108	        Reservation reservation = getReservation(id);
   109	
   110	        if (reservation.getStatus() != Reservation.Status.CHECKED_IN) {
   111	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   112	        }
   113	
   114	        reservation.setStatus(Reservation.Status.CHECKED_OUT);
   115	        reservationRepository.update(reservation);
   116	        return reservation;
   117	    }
   118	
   119	    public Reservation cancel(long id) {
   120	        Reservation reservation = getReservation(id);
   121	
   122	        if (reservation.getStatus() != Reservation.Status.PENDING && reservation.getStatus() != Reservation.Status.CONFIRMED) {
   123	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   124	        }
   125	
   126	        boolean wasConfirmed = reservation.getStatus() == Reservation.Status.CONFIRMED;
   127	        reservation.setStatus(Reservation.Status.CANCELLED);
   128	
   129	        if (wasConfirmed) {
   130	            if (reservation.getRatePlan() == Reservation.RatePlan.STANDARD) {
   131	                reservation.setRefund(reservation.getAmountPaid());
   132	            } else {
   133	                reservation.setRefund(BigDecimal.ZERO);
   134	            }
   135	        } else {
   136	            reservation.setRefund(BigDecimal.ZERO);
   137	        }
   138	
   139	        reservationRepository.update(reservation);
   140	        return reservation;
   141	    }
   142	
   143	    private BigDecimal calculateNightsCost(Room room, LocalDate checkIn, LocalDate checkOut) {
   144	        BigDecimal totalCost = BigDecimal.ZERO;
   145	        LocalDate current = checkIn;
   146	
   147	        while (current.isBefore(checkOut)) {
   148	            BigDecimal nightCost = room.nightlyRate();
   149	
   150	            if (Season.isHighSeason(current)) {
   151	                BigDecimal markupFactor = BigDecimal.valueOf(100 + Season.getMarkupPercent()).divide(BigDecimal.valueOf(100), 2, java.math.RoundingMode.HALF_EVEN);
   152	                nightCost = Money.multiply(nightCost, markupFactor);
   153	            }
   154	
   155	            nightCost = Money.round(nightCost);
   156	            totalCost = Money.add(totalCost, nightCost);
   157	            current = current.plusDays(1);
   158	        }
   159	
   160	        return totalCost;
   161	    }
