    27	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    28	                                       LocalDate checkIn, LocalDate checkOut, int guests, Reservation.RatePlan ratePlan) {
    29	        Optional<Room> room = roomRepository.findByNumber(roomNumber);
    30	        if (room.isEmpty()) {
    31	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    32	        }
    33	
    34	        if (guests < 1) {
    35	            throw new IllegalArgumentException("INVALID_REQUEST");
    36	        }
    37	
    38	        if (guests > room.get().capacity()) {
    39	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
    40	        }
    41	
    42	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
    43	            throw new IllegalArgumentException("INVALID_REQUEST");
    44	        }
    45	
    46	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
    47	        if (!conflicts.isEmpty()) {
    48	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    49	        }
    50	
    51	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    52	        BigDecimal subtotal = calculateNightsCost(room.get(), checkIn, checkOut);
    53	        BigDecimal discount = calculateDiscount(subtotal, ratePlan);
    54	        BigDecimal total = Money.subtract(subtotal, discount);
    55	
    56	        Reservation reservation = new Reservation();
    57	        reservation.setRoomNumber(roomNumber);
    58	        reservation.setGuestName(guestName);
    59	        reservation.setGuestEmail(guestEmail);
    60	        reservation.setGuestCpf(guestCpf);
    61	        reservation.setCheckIn(checkIn);
    62	        reservation.setCheckOut(checkOut);
    63	        reservation.setGuests(guests);
    64	        reservation.setRatePlan(ratePlan);
    65	        reservation.setNights(nights);
    66	        reservation.setSubtotal(subtotal);
    67	        reservation.setDiscount(discount);
    68	        reservation.setTotal(total);
    69	        reservation.setStatus(Reservation.Status.PENDING);
    70	        reservation.setAmountPaid(BigDecimal.ZERO);
    71	        reservation.setRefund(null);
    72	
    73	        return reservationRepository.save(reservation);
