   143	    private BigDecimal calculateNightsCost(Room room, LocalDate checkIn, LocalDate checkOut) {
   144	        BigDecimal totalCost = BigDecimal.ZERO;
   145	        LocalDate current = checkIn;
   146	
   147	        while (current.isBefore(checkOut)) {
   148	            BigDecimal nightCost = room.nightlyRate();
   149	
   150	            if (Season.isHighSeason(current)) {
   151	                BigDecimal markupFactor = BigDecimal.valueOf(100 + Season.getMarkupPercent()).divide(BigDecimal.valueOf(100), 2, java.math.RoundingMode.HALF_EVEN);
   152	                nightCost = Money.multiply(nightCost, markupFactor);
   153	            }
   154	
   155	            nightCost = Money.round(nightCost);
   156	            totalCost = Money.add(totalCost, nightCost);
   157	            current = current.plusDays(1);
   158	        }
   159	
   160	        return totalCost;
